export class Label {
  public readonly id: string;
  public readonly name: string;

  public constructor(id: string, name: string) {
    this.id = id;
    this.name = name;
  }
}

function makeBase(name: string): string {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  return base || "label";
}

export function generateLabels(names: readonly string[]): Label[] {
  const cleaned = names.map((name) => name.trim());
  if (cleaned.some((name) => name.length === 0)) {
    throw new TypeError("Label names must not be empty");
  }

  const counts = new Map<string, number>();
  return cleaned.map((name) => {
    const base = makeBase(name);
    const occurrence = (counts.get(base) ?? 0) + 1;
    counts.set(base, occurrence);
    const id = occurrence === 1 ? base : `${base}-${occurrence - 1}`;
    return new Label(id, name);
  });
}

