import { generateLabels, Label } from "./solution";

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function expectTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const names = ["  Red Apple  ", "red-apple", "RED   APPLE", "Blue_Berry", "!!!", "???", "Café"];
const snapshot = names.slice();
const labels = generateLabels(names);
const expected = [
  ["red-apple", "Red Apple"],
  ["red-apple-2", "red-apple"],
  ["red-apple-3", "RED   APPLE"],
  ["blue-berry", "Blue_Berry"],
  ["label", "!!!"],
  ["label-2", "???"],
  ["caf", "Café"],
];

equal(labels.length, expected.length, "result length");
for (let index = 0; index < labels.length; index++) {
  equal(labels[index] instanceof Label, true, `entry ${index} is a Label`);
  equal(labels[index].id, expected[index][0], `entry ${index} id`);
  equal(labels[index].name, expected[index][1], `entry ${index} name`);
}
for (let index = 0; index < names.length; index++) {
  equal(names[index], snapshot[index], `input ${index} is unchanged`);
}

const constructed = new Label("id-1", "Name");
equal(constructed.id, "id-1", "constructor id");
equal(constructed.name, "Name", "constructor name");

const emptyFirst = generateLabels([]);
const emptySecond = generateLabels([]);
equal(emptyFirst.length, 0, "empty input result");
equal(emptyFirst === emptySecond, false, "empty calls return fresh arrays");

const invalid = ["valid", "   ", "later"];
const invalidSnapshot = invalid.slice();
expectTypeError(() => generateLabels(invalid), "whitespace-only name");
for (let index = 0; index < invalid.length; index++) {
  equal(invalid[index], invalidSnapshot[index], `invalid input ${index} is unchanged`);
}
expectTypeError(() => generateLabels(["\t\n"]), "empty name after trimming");

